namespace LectureMate.Core.Summary;

/// <summary>
/// A lecture summary generated by the model after the session; the user can edit and export it.
/// </summary>
/// <param name="Title">Short lecture title.</param>
/// <param name="KeyPoints">Main points in lecture order.</param>
/// <param name="Questions">Questions asked during the lecture, with answers.</param>
/// <param name="Terms">Terms introduced in the lecture, with definitions.</param>
/// <param name="Flashcards">Review cards; exported to CSV for Anki.</param>
public sealed record LectureSummary(
    string Title,
    IReadOnlyList<string> KeyPoints,
    IReadOnlyList<QaPair> Questions,
    IReadOnlyList<Term> Terms,
    IReadOnlyList<Flashcard> Flashcards);
